---@param isNeedSaveVoice_ boolean @ 某些种动作的人声能中断其它类型动作的人声, 反之则不能中断, 需要用此 flag 来做区分处理
function IdolLive3D_Sounds:PlaySound( sheetName_, cueName_, type_, go_, isNeedSaveVoice_ )
    if type(sheetName_)~="string" or type(cueName_)~="string" or type(type_)~="number" then 
        printError("参数异常, sheet: " .. tostring(sheetName_) .. "; cue:" .. tostring(cueName_) .. "; type:" .. tostring(type_) )
        return
    end 

    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')

    local sheetName = "Audio/" .. sheetName_

    local soundSlice = nil
    if type_ == IdolLive3D_States.CueType.SFX then
        soundSlice = CriWareUtils.PlaySe(sheetName, cueName_, go_ ) -- 默认为 self.sfxSourceGO

    elseif type_ == IdolLive3D_States.CueType.BGM then
        soundSlice = CriWareUtils.PlayMusic(sheetName, cueName_, nil )
        
    elseif type_ == IdolLive3D_States.CueType.Voice then
        soundSlice = CriWareUtils.PlayVoice(sheetName, cueName_, go_ )

        if isNeedSaveVoice_ == true and isNotNull(soundSlice) then 

            local key = IdolLive3D_Sounds.BuildKey(sheetName_,cueName_)
            -- todo: 允许被重复触发:
            -- if self:IsVoicePlaying(key) then
            --     printError("异常, 容器 playingVoiceMap 中存在目标值: " .. tostring(key) )
            -- end
            self.playingVoiceMap[key] = 1

            soundSlice.onFinish = function()
                self:RemoveFromPlayingVoiceMap(key)
            end
        end

    else 
        printError("type 类型异常: " .. tostring(type_) )
    end 
end


function IdolLive3D_Sounds:RemoveFromPlayingVoiceMap(key_)
    key_ = tostring(key_)
    -- if self:IsVoicePlaying(key_) == false then
    --     printError("异常, 容器 playingVoiceMap 中没找到 目标值: " .. tostring(key_) )
    -- end
    self.playingVoiceMap[key_] = nil
    --printError("成功删除 voice " .. tostring(key_) )
end


---@return boolean
function IdolLive3D_Sounds:IsVoicePlaying( key_ ) 
    key_ = tostring(key_)
    return (self.playingVoiceMap[key_] ~= nil)
end


---@return boolean
function IdolLive3D_Sounds:IsAnyVoicePlaying() 
    return table.count(self.playingVoiceMap) > 0
end





function IdolLive3D_Sounds.StopAll()
    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
    CriWareUtils.StopAll()
end


function IdolLive3D_Sounds.Stop( sheetPath, cueName, soundType )
    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
    CriWareUtils.Stop(sheetPath, cueName, soundType)
end



function IdolLive3D_Sounds.IsSoundValid( sound_ )
    local ret = isTable(sound_) and type(sound_.sheetName)=="string" and  type(sound_.cueName)=="string" and  type(sound_.soundType)=="number"
    return ret
end




function IdolLive3D_Sounds.BuildKey( sheetName_, cueName_ )
    return tostring(sheetName_) .. "-" .. tostring(cueName_)
end



-- 在 role 体内准备 CriAtomSource go, 用它专门来播放 sfx, 以此克服 sfx 音源抢占 嘴型的问题;
function IdolLive3D_Sounds:AddCRIAtomSource_SFX( parent_ )
    self.sfxSourceGO = GameObject( "criAtomSource_sfx" )
    local tf = self.sfxSourceGO.transform 
    tf:SetParent(parent_)
    tf.localPosition = Vector3.zero 
    KTool.GetOrAddComponent(self.sfxSourceGO, typeof(CriAtomSource))
end



return IdolLive3D_Sounds